-- Forever News: patch notes for WoW Forever, readable in-game, filterable by class, searchable, copyable.
-- Data: News.lua (generated by tools/Update-News.ps1), Summaries.lua (hand/AI-written highlights).

local ADDON = ...
local data = ForeverNewsData or { generated = "?", items = {} }
local summaries = ForeverNewsSummaries or {}

local CLASS_ORDER = { "DRUID", "HUNTER", "MAGE", "PALADIN", "PRIEST", "ROGUE", "SHAMAN", "WARLOCK", "WARRIOR" }
local VALID_CLASS = {}
for _, token in ipairs(CLASS_ORDER) do VALID_CLASS[token] = true end

local SCHEMA = 2
local selectedIndex = 1 -- items are sorted newest first

local function ClassLabel(token)
    local names = LOCALIZED_CLASS_NAMES_MALE
    if names and names[token] then return names[token] end
    return token:sub(1, 1) .. token:sub(2):lower()
end

---------------------------------------------------------------------------
-- Language: the addon follows the language of the game client (GetLocale()).
-- English is the base language: the English text is also the lookup key, so English needs no table.
-- Translations live in Locales.lua. Anything that is missing falls back to English.
---------------------------------------------------------------------------
local LOCALE = GetLocale()
local TEXTS = (ForeverNewsLocales and ForeverNewsLocales[LOCALE]) or {}
local LANG = LOCALE:sub(1, 2)   -- "de", "en", "fr" ...: which short summary to show (falls back to "en")

local function L(key) return TEXTS[key] or key end

local EN_MONTHS = { "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" }

-- One date format per language: long for the headline, short for the list
local function LongDate(iso)
    local y, m, d = (iso or ""):match("^(%d+)-(%d+)-(%d+)$")
    if not y then return iso or "" end
    local name = (TEXTS._months or EN_MONTHS)[tonumber(m)] or m
    if TEXTS._dateLong then return TEXTS._dateLong:format(tonumber(d), name, y) end   -- e.g. "%d. %s %s"
    return ("%s %d, %s"):format(name, tonumber(d), y)                                  -- "November 6, 2026"
end

local function ShortDate(iso)
    local y, m, d = (iso or ""):match("^(%d+)-(%d+)-(%d+)$")
    if not y then return iso or "" end
    if TEXTS._dateShort then return TEXTS._dateShort:format(d, m, y) end   -- e.g. "%s.%s.%s"
    return iso                                                             -- "2026-11-06"
end

-- Short name without the date (the date is shown once, separately)
local function DisplayName(item)
    if item.category == "Hotfixes" then return "Hotfixes" end
    if item.category == "Patch Notes" then return "Patch Notes" end
    return item.title
end

-- The grey line under the title: the date once, plus what kind of entry it is
local function MetaLine(item, filterName, classPicked)
    local line = LongDate(item.date)
    if item.category == "Hotfixes" then line = L("Status as of %s"):format(line) end
    if item.category == "Announcement" then line = L("Announcement of %s"):format(line) end
    if classPicked then line = line .. "  ·  " .. filterName end
    return line
end

local function db()
    ForeverNewsDB = ForeverNewsDB or {}
    local d = ForeverNewsDB
    d.read = d.read or {}
    if d.schema ~= SCHEMA then
        d.schema = SCHEMA
        d.classFilter = "ALL" -- default: show everything
    end
    if d.classFilter == nil or (d.classFilter ~= "ALL" and not VALID_CLASS[d.classFilter]) then d.classFilter = "ALL" end
    if d.overviewOnly == nil then d.overviewOnly = false end
    return d
end

-- An entry counts as read only while it is unchanged since you read it. The read mark stores the entry's date,
-- so Blizzard's hotfix article (one page that grows, its date moves on) turns "unread" again when it gets news.
-- Old marks (just "true", from earlier versions) count as read for entries up to 2026-11-08 only.
local function IsRead(item)
    local mark = db().read[item.id]
    if mark == nil then return false end
    if mark == true then return tostring(item.date) <= "2026-11-08" end
    return mark == item.date
end

local function UnreadCount()
    local n = 0
    for _, item in ipairs(data.items) do
        if not IsRead(item) then n = n + 1 end
    end
    return n
end

---------------------------------------------------------------------------
-- Content model: a list of blocks, serialised once as coloured text (reading view)
-- and once as plain text (copy view).
-- block kinds: title, meta, blank, hdr, note, class, group, sub, li, patch
---------------------------------------------------------------------------
-- Search helpers. A search is a list of words; a line is a hit only if it contains ALL of them
-- (so "stormstrike cooldown" narrows the result instead of widening it).
local function MatchesAll(lowerText, terms)
    for _, t in ipairs(terms) do
        if not lowerText:find(t, 1, true) then return false end   -- true = plain text, no pattern magic
    end
    return true
end

-- With "Alle" everything is shown. With one class picked, only that class's sections are shown
-- (general changes such as items, quests or dungeons belong to "Alle").
local function SectionVisible(sec, classFilter)
    if sec.c ~= "" then
        return classFilter == "ALL" or sec.c == classFilter
    end
    return classFilter == "ALL"
end

-- Blizzard's hotfix article is ONE page that keeps growing: every section says on which day it was added
-- ("Cooldown Manager / November 6, 2026"). This splits the day off the end: returns the rest and the day as "2026-11-06".
local MONTH_NUMBER = {}
for i, name in ipairs(EN_MONTHS) do MONTH_NUMBER[name] = i end
local function SplitDay(s)
    local day = (s or ""):match("(%a+ %d+, %d%d%d%d)$")
    local month, d, y = (day or ""):match("^(%a+) (%d+), (%d+)$")
    if not (month and MONTH_NUMBER[month]) then return s or "", nil end
    local rest = (s:sub(1, #s - #day):gsub("%s*/%s*$", ""))
    return rest, ("%04d-%02d-%02d"):format(tonumber(y), MONTH_NUMBER[month], tonumber(d))
end

local function AddSections(blocks, item, classFilter, query)
    -- if the entry spans several days (the hotfix article), every day gets its own heading, newest first
    local dayCount, seen = 0, {}
    for _, sec in ipairs(item.sections) do
        local _, iso = SplitDay(sec.s)
        if iso and not seen[iso] then seen[iso] = true; dayCount = dayCount + 1 end
    end
    local lastKey, lastDay, added = nil, nil, 0
    for _, sec in ipairs(item.sections) do
        if SectionVisible(sec, classFilter) then
            local items = {}
            for _, line in ipairs(sec.lines) do
                if not query or MatchesAll(line:lower(), query) then
                    local indent, rest = line:match("^(%s*)(.*)$")
                    items[#items + 1] = { k = "li", indent = math.floor(#indent / 2), text = rest, terms = query }
                end
            end
            if #items > 0 then
                local head, key, subParts = nil, nil, {}
                if sec.c ~= "" then
                    head, key = ClassLabel(sec.c):upper(), sec.c
                    if sec.g ~= "" and sec.g ~= "Classes" then subParts[#subParts + 1] = L(sec.g) end
                else
                    head, key = L(sec.g ~= "" and sec.g or "General"), "g:" .. sec.g
                end
                local subText, iso = SplitDay(sec.s)   -- the day is shown in the heading / title instead
                if subText ~= "" then subParts[#subParts + 1] = L(subText) end

                if dayCount > 1 and iso and iso ~= lastDay then
                    blocks[#blocks + 1] = { k = "day", text = LongDate(iso) }
                    lastDay, lastKey = iso, nil   -- a new day starts: show the group heading again
                end
                if key ~= lastKey then
                    blocks[#blocks + 1] = { k = sec.c ~= "" and "class" or "group", text = head, token = sec.c }
                    lastKey = key
                end
                if #subParts > 0 then blocks[#blocks + 1] = { k = "sub", text = table.concat(subParts, " / ") } end
                for _, b in ipairs(items) do blocks[#blocks + 1] = b end
                added = added + #items
            end
        end
    end
    return added
end

-- Search hits in the short summary (in the client's language). Because that text is in the player's own
-- language, a German player who types "Schaden" or "Katze" finds something, although Blizzard's notes are English.
local function AddSummaryHits(blocks, item, classFilter, terms)
    local entry = summaries[item.id]
    local s = entry and entry.date == item.date and (entry[LANG] or entry.en)
    if not s then return 0 end
    local out, added = {}, 0
    local function Collect(lines, header)
        local hits = {}
        for _, line in ipairs(lines or {}) do
            if MatchesAll(line:lower(), terms) then hits[#hits + 1] = { k = "li", indent = 0, text = line, terms = terms } end
        end
        if #hits > 0 then
            if header then out[#out + 1] = header end
            for _, h in ipairs(hits) do out[#out + 1] = h end
            added = added + #hits
        end
    end
    if classFilter == "ALL" then Collect(s.overall, nil) end   -- general points belong to "All", like the details
    for _, token in ipairs(CLASS_ORDER) do
        if classFilter == "ALL" or classFilter == token then
            Collect(s.classes and s.classes[token], { k = "class", text = ClassLabel(token):upper(), token = token })
        end
    end
    if added > 0 then
        blocks[#blocks + 1] = { k = "sub", text = L("Summary") }
        for _, b in ipairs(out) do blocks[#blocks + 1] = b end
    end
    return added
end

local function HiddenGeneralCount(item)
    local n = 0
    for _, sec in ipairs(item.sections) do
        if sec.c == "" then n = n + #sec.lines end
    end
    return n
end

-- Plain text (for copying)
local function ToPlain(blocks)
    local out = {}
    for _, b in ipairs(blocks) do
        local k = b.k
        if k == "title" or k == "meta" then out[#out + 1] = b.text
        elseif k == "blank" then out[#out + 1] = ""
        elseif k == "hdr" then out[#out + 1] = ""; out[#out + 1] = "=== " .. b.text .. " ==="
        elseif k == "ohdr" then out[#out + 1] = ""; out[#out + 1] = "=== " .. b.text .. " ==="
        elseif k == "day" then out[#out + 1] = ""; out[#out + 1] = "######## " .. b.text .. " ########"
        elseif k == "note" then out[#out + 1] = "(" .. b.text .. ")"
        elseif k == "class" or k == "group" then out[#out + 1] = ""; out[#out + 1] = "== " .. b.text .. " =="
        elseif k == "sub" then out[#out + 1] = "-- " .. b.text .. " --"
        elseif k == "patch" then out[#out + 1] = ""; out[#out + 1] = "######## " .. b.text .. " ########"
        elseif k == "li" then out[#out + 1] = string.rep("  ", b.indent or 0) .. "- " .. b.text
        end
    end
    return table.concat(out, "\n")
end

-- Coloured text (for reading)
-- Colour carries meaning, and only a few words get it (too much colour = nothing stands out):
-- green = stronger / new, red = removed / weaker. Words, not only colour, say the same thing
-- (about 1 in 12 men cannot tell red from green).
local POSITIVE = { "increased", "Increased", "raised", "Raised", "improved", "Improved", "doubled", "Doubled", "erhöht", "verdoppelt",
                   "stärker", "Neu", "Neue", "Neuer", "Neues" }
local NEGATIVE = { "reduced", "Reduced", "removed", "Removed", "decreased", "Decreased", "lowered", "Lowered", "entfernt", "reduziert",
                   "weg", "Weg" }

local C_WAS, C_UP, C_DOWN, C_HIT = "9a9a9a", "7fe07f", "ff8a7a", "ff9a1f"

-- Colours one line. IMPORTANT: every piece of text is its own run, "|cffRRGGBB text |r": opened and closed right
-- there. Nothing is ever nested or left open. (The game stops obeying colour codes in a text once too many are
-- left open: that is why the highlighting used to vanish further down in long search results.)
-- Later Paint calls win over earlier ones, so the search hit is painted last and always shows.
local function Colorize(text, base, terms)
    local col = {}   -- col[i] = colour of byte i (nil = the line's normal colour)

    local function Paint(pattern, color, plain)
        local from = 1
        while true do
            local s, e = text:find(pattern, from, plain)
            if not s then break end
            for i = s, e do col[i] = color end
            from = e + 1
        end
    end

    Paint("%([Ww]as[^)]*%)", C_WAS)                        -- "(was 10%)" is the old value: grey
    Paint("%+%d[%d,%.]*%s?%%", C_UP)                       -- "+110 %" reads as "more": green
    for _, w in ipairs(POSITIVE) do Paint("%f[%a]" .. w .. "%f[%A]", C_UP) end
    for _, w in ipairs(NEGATIVE) do Paint("%f[%a]" .. w .. "%f[%A]", C_DOWN) end
    if terms then
        local lower = text:lower()
        for _, t in ipairs(terms) do
            local from = 1
            while true do
                local s, e = lower:find(t, from, true)    -- true = plain text
                if not s then break end
                for i = s, e do col[i] = C_HIT end        -- vivid orange: the searched words
                from = e + 1
            end
        end
    end

    -- put neighbouring characters with the same colour together into runs
    local out, runStart, runCol, n = {}, 1, col[1] or base, #text
    for i = 2, n + 1 do
        local c = (i <= n) and (col[i] or base) or nil
        if c ~= runCol then
            out[#out + 1] = "|cff" .. runCol .. (text:sub(runStart, i - 1):gsub("|", "||")) .. "|r"
            runStart, runCol = i, c
        end
    end
    return table.concat(out)
end

local function EscapePipes(text) return (text:gsub("|", "||")) end

-- skipHead: the title and subtitle (first two blocks) are drawn in a fixed header above the text instead
local function ToRich(blocks, skipHead)
    local out = {}
    for i, b in ipairs(blocks) do
      if not (skipHead and i <= 2) then
        local k = b.k
        if k == "title" then out[#out + 1] = "|cffffd100" .. EscapePipes(b.text) .. "|r"
        elseif k == "meta" then out[#out + 1] = "|cff9a9a9a" .. EscapePipes(b.text) .. "|r"
        elseif k == "blank" then out[#out + 1] = ""
        elseif k == "hdr" then out[#out + 1] = ""; out[#out + 1] = "|cff4dd2ff" .. EscapePipes(b.text) .. "|r"
        elseif k == "ohdr" then out[#out + 1] = "|cffffd100" .. EscapePipes(b.text) .. "|r"   -- heading of Blizzard's original text
        elseif k == "day" then out[#out + 1] = ""; out[#out + 1] = "|cffffd100" .. EscapePipes(b.text) .. "|r"   -- one day of a growing article
        elseif k == "note" then
            if not b.plainOnly then out[#out + 1] = "|cffb0b0b0" .. EscapePipes(b.text) .. "|r" end   -- plainOnly: only in the copy text
        elseif k == "patch" then out[#out + 1] = ""; out[#out + 1] = "|cffffd100" .. EscapePipes(b.text) .. "|r"
        elseif k == "class" then
            local c = RAID_CLASS_COLORS and RAID_CLASS_COLORS[b.token]
            local col = (c and c.colorStr) or "ffffffff"
            out[#out + 1] = ""
            out[#out + 1] = "|c" .. col .. EscapePipes(b.text) .. "|r"
        elseif k == "group" then
            out[#out + 1] = ""
            out[#out + 1] = "|cffffd100" .. EscapePipes(b.text:upper()) .. "|r"
        elseif k == "sub" then out[#out + 1] = "|cff66ccff" .. EscapePipes(b.text) .. "|r"
        elseif k == "li" then
            local dev = b.text:find("^Developer") ~= nil
            local base = dev and "b0b0b0" or ((b.indent or 0) > 0 and "d0d0d0" or "ffffff")
            -- in search results the rest of the line steps back a little, so the highlighted words stand out more
            if b.terms and not dev then base = (b.indent or 0) > 0 and "a8a8a8" or "c4c4c4" end
            -- the one warning that matters most ("planned, not live yet") stands out in orange
            if (b.indent or 0) == 0 and b.text:find("^" .. L("Planned")) then base = "ffb347" end
            local bullet = (b.indent or 0) > 0 and "-" or "•"
            out[#out + 1] = string.rep("    ", b.indent or 0) .. "|cff" .. base .. bullet .. " |r" .. Colorize(b.text, base, b.terms)
        end
      end
    end
    return table.concat(out, "\n")
end

---------------------------------------------------------------------------
-- Main window
---------------------------------------------------------------------------
-- Native look: the game's own window border ("ButtonFrameTemplateNoPortrait", which WoW Forever draws in
-- bronze) over its dark rock background, with the title in the title bar and the normal close button.
-- If the client does not have that border kit, fall back to the classic dialog border.
-- Returns true when the native look was used.
local function DressWindow(f, title)
    local util = _G.NineSliceUtil
    local layout = util and util.GetLayout and util.GetLayout("ButtonFrameTemplateNoPortrait") and "ButtonFrameTemplateNoPortrait"
    local native = false
    if layout then
        local ok, nine = pcall(CreateFrame, "Frame", nil, f, "NineSlicePanelTemplate")
        if ok and nine and pcall(util.ApplyLayoutByName, nine, layout) then
            nine:SetAllPoints()
            nine:SetFrameLevel(f:GetFrameLevel())
            local bg = f:CreateTexture(nil, "BACKGROUND")
            bg:SetPoint("TOPLEFT", 6, -21)
            bg:SetPoint("BOTTOMRIGHT", -2, 3)
            if bg:SetTexture("Interface\\FrameGeneral\\UI-Background-Rock", "REPEAT", "REPEAT") == false then
                bg:SetColorTexture(0.1, 0.09, 0.08, 1)
            end
            bg:SetHorizTile(true)
            bg:SetVertTile(true)
            local shade = f:CreateTexture(nil, "BACKGROUND", nil, 1)
            shade:SetAllPoints(bg)
            shade:SetColorTexture(0, 0, 0, 0.45) -- darkens the rock so small text stays readable
            native = true
        end
    end
    if not native and f.SetBackdrop then
        f:SetBackdrop({
            bgFile = "Interface\\DialogFrame\\UI-DialogBox-Background-Dark",
            edgeFile = "Interface\\DialogFrame\\UI-DialogBox-Gold-Border",
            tile = true, tileSize = 32, edgeSize = 32,
            insets = { left = 11, right = 12, top = 12, bottom = 11 },
        })
    end
    local text = f:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    text:SetPoint("TOPLEFT", native and 30 or 16, native and -4 or -12)
    text:SetPoint("TOPRIGHT", -30, native and -4 or -12)
    text:SetJustifyH(native and "CENTER" or "LEFT")
    text:SetWordWrap(false)
    text:SetText(title)
    local close = CreateFrame("Button", nil, f, "UIPanelCloseButton")
    close:SetFrameLevel(f:GetFrameLevel() + 20)
    if native then close:SetPoint("TOPRIGHT", 1, 0) else close:SetPoint("TOPRIGHT", 2, 2) end
    close:SetScript("OnClick", function() f:Hide() end)
    return native
end

-- Modern thin scroll bar (like the game's own windows), classic one as fallback.
local function MakeScroll(parent)
    local ok, sf = pcall(CreateFrame, "ScrollFrame", nil, parent, "ScrollFrameTemplate")
    if not ok or not sf then
        sf = CreateFrame("ScrollFrame", nil, parent, "UIPanelScrollFrameTemplate")
    end
    return sf
end

