-- Rendering
---------------------------------------------------------------------------
-- The search text as a list of lower-case words (words shorter than 2 letters are ignored while typing).
local function CurrentQuery()
    local terms = {}
    for word in strtrim(search:GetText() or ""):lower():gmatch("%S+") do
        if #word >= 2 then terms[#terms + 1] = word end
    end
    if #terms == 0 then return nil end
    return terms
end

local function AddSummary(blocks, item, classFilter)
    local entry = summaries[item.id]
    if not entry then return false end
    -- the summary in the client's language, English if there is none for it
    local s = entry[LANG] or entry.en
    if not s then return false end
    if entry.date ~= item.date then
        blocks[#blocks + 1] = { k = "hdr", text = L("Key points") }
        blocks[#blocks + 1] = { k = "note", text = L("The summary is outdated. Please read the details below.") }
        return false
    end
    blocks[#blocks + 1] = { k = "hdr", text = L("Key points") }
    -- the AI hint is shown once, small, in the box header (with this sentence as tooltip); the copy text keeps it
    blocks[#blocks + 1] = { k = "note", plainOnly = true, text = L("Short summary by an AI. The details below are what counts.") }
    if classFilter == "ALL" or classFilter == nil then
        for _, line in ipairs(s.overall or {}) do blocks[#blocks + 1] = { k = "li", indent = 0, text = line } end
        for _, token in ipairs(CLASS_ORDER) do
            local lines = s.classes and s.classes[token]
            if lines then
                blocks[#blocks + 1] = { k = "class", text = ClassLabel(token):upper(), token = token }
                for _, line in ipairs(lines) do blocks[#blocks + 1] = { k = "li", indent = 0, text = line } end
            end
        end
    else
        for _, line in ipairs(s.overall or {}) do blocks[#blocks + 1] = { k = "li", indent = 0, text = line } end
        local lines = s.classes and s.classes[classFilter]
        if lines then
            blocks[#blocks + 1] = { k = "class", text = ClassLabel(classFilter):upper(), token = classFilter }
            for _, line in ipairs(lines) do blocks[#blocks + 1] = { k = "li", indent = 0, text = line } end
        end
    end
    return true
end

refresh = function()
    local d = db()
    local query = CurrentQuery()
    local blocks = {}
    local sum = {}   -- blocks of the AI summary box (only used outside of searching)
    local filterName = d.classFilter == "ALL" and L("All classes") or ClassLabel(d.classFilter)

    if query then
        local total, patches, body = 0, 0, {}
        for _, item in ipairs(data.items) do
            local tmp = {}
            local nSummary = AddSummaryHits(tmp, item, d.classFilter, query)   -- short summary first ...
            local details = {}
            local nDetails = AddSections(details, item, d.classFilter, query)   -- ... then Blizzard's detailed notes
            if nSummary > 0 and nDetails > 0 then tmp[#tmp + 1] = { k = "sub", text = L("Details") } end
            for _, b in ipairs(details) do tmp[#tmp + 1] = b end
            local n = nSummary + nDetails
            if n > 0 then
                body[#body + 1] = { k = "patch", text = DisplayName(item) .. "  ·  " .. LongDate(item.date) }
                for _, b in ipairs(tmp) do body[#body + 1] = b end
                total, patches = total + n, patches + 1
            end
        end
        blocks[1] = { k = "title", text = L('Search "%s"'):format(table.concat(query, " ")) }
        blocks[2] = { k = "meta", text = L("Filter: %s | %d hits in %d patch(es)"):format(filterName, total, patches) }
        for _, b in ipairs(body) do blocks[#blocks + 1] = b end
        if total == 0 then blocks[#blocks + 1] = { k = "note", text = L("No hits.") } end
    else
        local item = data.items[selectedIndex]
        if not item then
            SetBody(L("No patch notes yet.") .. "\n" .. L("Run tools\\Update-News.cmd and reload the interface (/reload)."),
                    L("No patch notes yet."))
            return
        end
        blocks[1] = { k = "title", text = DisplayName(item) }
        blocks[2] = { k = "meta", text = MetaLine(item, filterName, d.classFilter ~= "ALL") }

        local hasSummary = AddSummary(sum, item, d.classFilter)
        local showDetails = not (d.overviewOnly and hasSummary)

        if showDetails then
            if hasSummary then blocks[#blocks + 1] = { k = "ohdr", text = L("Original patch notes (Blizzard)") } end
            local n = AddSections(blocks, item, d.classFilter, nil)
            if n == 0 then blocks[#blocks + 1] = { k = "note", text = L("No changes for this selection in this patch.") } end
            if d.classFilter ~= "ALL" then
                local hidden = HiddenGeneralCount(item)
                if hidden > 0 then
                    blocks[#blocks + 1] = { k = "blank" }
                    blocks[#blocks + 1] = { k = "note", text = L("%d general changes hidden - pick \"All\" to see them"):format(hidden) }
                end
            end
        elseif d.overviewOnly and not hasSummary then
            blocks[#blocks + 1] = { k = "note", text = L("There is no summary for this entry.") }
        end
        blocks[#blocks + 1] = { k = "blank" }
        blocks[#blocks + 1] = { k = "meta", text = L("Source: ") .. item.url }
    end
    -- the summary box gets its own text; for copying, everything goes back together in reading order
    local sumRich, sumLabel, all = nil, nil, blocks
    if #sum > 0 then
        sumLabel = sum[1].text                      -- the "Key points" heading becomes the box header
        local rest = {}
        for i = 2, #sum do rest[#rest + 1] = sum[i] end
        sumRich = ToRich(rest, false)
        all = { blocks[1], blocks[2] }
        for _, b in ipairs(sum) do all[#all + 1] = b end
        for i = 3, #blocks do all[#all + 1] = blocks[i] end
    end
    SetBody(ToRich(blocks, true), ToPlain(all), blocks[1].text, blocks[2].text, sumRich, sumLabel)
    if copyMode then edit:SetFocus(); edit:HighlightText() end
end

local function UpdateListMarks()
    for i, b in ipairs(buttons) do
        local isRead = IsRead(data.items[i])
        b.selected:SetShown(i == selectedIndex)
        b.dot:SetShown(not isRead)
        -- unread = gold, already read = soft grey (so new entries stand out at a glance)
        if isRead then b.title:SetTextColor(0.82, 0.82, 0.82) else b.title:SetTextColor(1, 0.82, 0) end
    end
end

local function ShowItem(index)
    local item = data.items[index]
    if not item then return end
    selectedIndex = index
    db().read[item.id] = item.date   -- remember the state we have read (see IsRead)
    UpdateListMarks()
    refresh()
    if ForeverNewsMinimapButton then ForeverNewsMinimapButton.UpdateBadge() end
end

local function BuildList()
    for i, item in ipairs(data.items) do
        local b = buttons[i]
        if not b then
            b = CreateFrame("Button", nil, listChild)
            b:SetSize(176, 38)
            b:SetPoint("TOPLEFT", 0, -(i - 1) * 40)
            b:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD")
            b.selected = b:CreateTexture(nil, "BACKGROUND")
            b.selected:SetAllPoints()
            b.selected:SetColorTexture(1, 0.82, 0, 0.15)
            b.selected:Hide()
            b.dot = b:CreateTexture(nil, "OVERLAY")
            b.dot:SetSize(8, 8)
            b.dot:SetPoint("LEFT", 2, 0)
            b.dot:SetColorTexture(0.3, 0.8, 1, 1)
            b.title = b:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
            b.title:SetPoint("TOPLEFT", 14, -3)
            b.title:SetPoint("TOPRIGHT", -2, -3)
            b.title:SetJustifyH("LEFT")
            b.title:SetWordWrap(false)
            b.sub = b:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
            b.sub:SetPoint("BOTTOMLEFT", 14, 4)
            b:SetScript("OnClick", function()
                search:SetText("") -- leave search mode, show this patch
                ShowItem(i)
            end)
            buttons[i] = b
        end
        -- line 1: what it is; line 2: the date (once) and a hint if a short summary exists
        b.title:SetText(DisplayName(item))
        local s = summaries[item.id]
        local hasSummary = s and s.date == item.date
        b.sub:SetText(ShortDate(item.date) .. (hasSummary and (" · " .. L("Summary")) or ""))
    end
    listChild:SetHeight(math.max(1, #data.items * 40))
    UpdateListMarks()
end

-- HookScript (not SetScript) keeps the search box template's own behaviour (hint text, clear button)
search:HookScript("OnTextChanged", function(self)
    if placeholder then placeholder:SetShown((self:GetText() or "") == "") end
    refresh()
end)
search:SetScript("OnEscapePressed", function(self)
    if (self:GetText() or "") ~= "" then self:SetText("") else self:ClearFocus() end
end)
