-- News button: looks like the chat "Social" button and sits right above it by default.
-- It can be dragged while Blizzard's Edit Mode is open; the position is saved.
---------------------------------------------------------------------------
local newsBtn = CreateFrame("Button", "ForeverNewsButton", UIParent)
newsBtn:SetSize(32, 32)
newsBtn:SetFrameStrata("MEDIUM")
newsBtn:SetClampedToScreen(true)
newsBtn:RegisterForClicks("LeftButtonUp")

-- width relative to the Social button when hanging directly beneath it (1 = same width); lower = slimmer
local NEWS_WIDTH_FACTOR = 0.9
-- size relative to the neighbouring chat button when hanging beneath it. Below 1 because the game's buttons have
-- some empty margin inside their frame, while our button art fills the whole frame (1 = same frame size).
local NEWS_NEIGHBOUR_SCALE = 0.85

-- solid dark backing, so the wall behind the button does not shine through (the Social button is dark, too)
newsBtn.back = newsBtn:CreateTexture(nil, "BACKGROUND", nil, -1)
newsBtn.back:SetPoint("TOPLEFT", 3, -3)
newsBtn.back:SetPoint("BOTTOMRIGHT", -3, 3)
newsBtn.back:SetColorTexture(0.04, 0.03, 0.02, 0.95)

-- yellow icon on top of the button art (the quest "!" symbol: yellow, and means "something new")
newsBtn.icon = newsBtn:CreateTexture(nil, "OVERLAY")
newsBtn.icon:SetPoint("CENTER")
newsBtn.icon:SetTexture("Interface\\GossipFrame\\AvailableQuestIcon")

newsBtn.count = newsBtn:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
newsBtn.count:SetPoint("BOTTOMRIGHT", -2, 2)
newsBtn.count:SetTextColor(0.3, 0.8, 1)

function newsBtn.UpdateBadge()
    local n = UnreadCount()
    newsBtn.count:SetText(n > 0 and tostring(n) or "")
end

local function AtlasExists(name)
    return name and C_Texture and C_Texture.GetAtlasInfo and C_Texture.GetAtlasInfo(name) ~= nil
end

local LowestChatButton   -- defined below (needs to be known here)

-- Copy size and art from the game's own chat buttons, so the look matches this client exactly.
local function StyleNewsButton()
    -- Size: the same as the button it sits beneath. The chat buttons below the Social button are smaller than the
    -- Social button itself, so copying the Social size would make ours look too big and bulky next to them.
    local neighbour = LowestChatButton and LowestChatButton()
    local sizeSource = neighbour or QuickJoinToastButton
    local ref = sizeSource and (sizeSource.FriendsButton or sizeSource)
    local w, h = 32, 32
    if ref and ref.GetSize then
        local rw, rh = ref:GetSize()
        if rw and rw > 8 and rh and rh > 8 then w, h = rw, rh end
    end
    local sw, sh
    if neighbour and neighbour ~= QuickJoinToastButton then
        sw, sh = w * NEWS_NEIGHBOUR_SCALE, h * NEWS_NEIGHBOUR_SCALE   -- beneath a smaller chat button
    else
        sw, sh = w * NEWS_WIDTH_FACTOR, h                             -- directly beneath the Social button
    end
    newsBtn:SetSize(sw, sh)
    newsBtn.icon:SetSize(math.min(sw, sh) * 0.62, math.min(sw, sh) * 0.62)

    -- the Social button shows "friends online"; ours shows "unread patches" in the same font, colour and spot
    local qj = QuickJoinToastButton
    local counters = { qj and qj.FriendCount, qj and qj.FriendsButton and qj.FriendsButton.Count,
                       ref and ref.Count, ref and ref.FriendCount }
    for _, c in pairs(counters) do
        if c and c.GetFontObject and c.GetPoint then
            local fo = c:GetFontObject()
            if fo then newsBtn.count:SetFontObject(fo) end
            local r, g, b = c:GetTextColor()
            if r then newsBtn.count:SetTextColor(r, g, b) end
            local point, _, relPoint, x, y = c:GetPoint(1)
            if point then
                newsBtn.count:ClearAllPoints()
                newsBtn.count:SetPoint(point, newsBtn, relPoint or point, x or 0, y or 0)
            end
            break
        end
    end

    local normal, pushed, highlight
    local sources = { QuickJoinToastButton and QuickJoinToastButton.FriendsButton, ChatFrameMenuButton, ChatFrameChannelButton }
    for _, b in pairs(sources) do
        local nt = b.GetNormalTexture and b:GetNormalTexture()
        local a = nt and nt.GetAtlas and nt:GetAtlas()
        if AtlasExists(a) then
            normal = a
            local pt = b.GetPushedTexture and b:GetPushedTexture()
            pushed = pt and pt.GetAtlas and pt:GetAtlas()
            local ht = b.GetHighlightTexture and b:GetHighlightTexture()
            highlight = ht and ht.GetAtlas and ht:GetAtlas()
            break
        end
    end
    -- known names as a fallback, a plain dark square if the client has neither
    normal = normal or (AtlasExists("chatframe-button-up") and "chatframe-button-up")
    if not AtlasExists(pushed) then pushed = AtlasExists("chatframe-button-down") and "chatframe-button-down" or nil end
    if not AtlasExists(highlight) then highlight = AtlasExists("chatframe-button-highlight") and "chatframe-button-highlight" or nil end

    if normal then
        newsBtn:SetNormalAtlas(normal)
        if pushed then newsBtn:SetPushedAtlas(pushed) end
        if highlight then newsBtn:SetHighlightAtlas(highlight) end
    elseif not newsBtn.fallbackBg then   -- (created only once, this function runs more than once)
        newsBtn.fallbackBg = newsBtn:CreateTexture(nil, "BACKGROUND")
        newsBtn.fallbackBg:SetAllPoints()
        newsBtn.fallbackBg:SetColorTexture(0, 0, 0, 0.85)
        newsBtn:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square", "ADD")
    end
end

-- The chat buttons (Social, channels, chat menu) sit in one column. Find the lowest one, so the News button
-- goes beneath the whole column and never covers another button.
LowestChatButton = function()
    local social = QuickJoinToastButton
    if not (social and social.GetCenter) then return nil end
    local socialX = social:GetCenter()
    local lowest, lowestBottom = social, social:GetBottom()
    for _, b in pairs({ ChatFrameChannelButton, ChatFrameMenuButton }) do
        if b and b.IsShown and b:IsShown() and b.GetCenter then
            local bx, bottom = b:GetCenter(), b:GetBottom()
            -- only count buttons in the same column (about the same horizontal position)
            if socialX and bx and bottom and math.abs(bx - socialX) < 30 and (not lowestBottom or bottom < lowestBottom) then
                lowest, lowestBottom = b, bottom
            end
        end
    end
    return lowest
end

local function PlaceNewsButton()
    local pos = db().newsPos
    local anchor = LowestChatButton()
    newsBtn:ClearAllPoints()
    if pos then
        newsBtn:SetPoint(pos.point, UIParent, pos.relPoint, pos.x, pos.y)
    elseif anchor then
        newsBtn:SetPoint("TOP", anchor, "BOTTOM", 0, -6)   -- default: beneath the Social button (and any button below it)
    else
        newsBtn:SetPoint("BOTTOMLEFT", UIParent, "BOTTOMLEFT", 20, 260)
    end
end

-- Edit Mode: show a blue frame around the button and allow dragging while Edit Mode is open
local editing = false
local sel = CreateFrame("Frame", nil, newsBtn, BackdropTemplateMixin and "BackdropTemplate" or nil)
sel:SetPoint("TOPLEFT", -3, 3)
sel:SetPoint("BOTTOMRIGHT", 3, -3)
sel:SetFrameLevel(newsBtn:GetFrameLevel() + 10)
sel:Hide()
if sel.SetBackdrop then
    sel:SetBackdrop({ edgeFile = "Interface\\Buttons\\WHITE8X8", edgeSize = 2 })
    sel:SetBackdropBorderColor(0.25, 0.65, 1, 1)
end
sel.label = sel:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
sel.label:SetPoint("BOTTOM", sel, "TOP", 0, 2)
sel.label:SetText("Forever News")

local function SetEditing(on)
    editing = on
    sel:SetShown(on)
    newsBtn:SetMovable(on)
    if on then newsBtn:RegisterForDrag("LeftButton") else newsBtn:RegisterForDrag() end
end
if EventRegistry and EventRegistry.RegisterCallback then
    EventRegistry:RegisterCallback("EditMode.Enter", function() SetEditing(true) end, newsBtn)
    EventRegistry:RegisterCallback("EditMode.Exit", function() SetEditing(false) end, newsBtn)
end

newsBtn:SetScript("OnDragStart", function(self) if editing then self:StartMoving() end end)
newsBtn:SetScript("OnDragStop", function(self)
    self:StopMovingOrSizing()
    -- save as a plain offset from the screen's bottom-left corner (independent of what it was anchored to before)
    local cx, cy = self:GetCenter()
    local scale = self:GetEffectiveScale() / UIParent:GetEffectiveScale()
    db().newsPos = { point = "CENTER", relPoint = "BOTTOMLEFT", x = cx * scale, y = cy * scale }
    PlaceNewsButton()
end)

newsBtn:SetScript("OnClick", function() if not editing then Toggle() end end)
newsBtn:SetScript("OnEnter", function(self)
    if editing then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    GameTooltip:AddLine("Forever News")
    GameTooltip:AddLine(L("%d unread patches"):format(UnreadCount()), 1, 1, 1)
    GameTooltip:AddLine(L("Movable in Edit Mode"), 0.6, 0.6, 0.6)
    GameTooltip:Show()
end)
newsBtn:SetScript("OnLeave", GameTooltip_Hide)

---------------------------------------------------------------------------
-- Events / slash command
---------------------------------------------------------------------------
local ev = CreateFrame("Frame")
ev:RegisterEvent("PLAYER_LOGIN")
ev:RegisterEvent("PLAYER_ENTERING_WORLD")   -- the chat buttons have their final positions by now: place again
ev:SetScript("OnEvent", function(_, event)
    if event == "PLAYER_ENTERING_WORLD" then
        StyleNewsButton()   -- size depends on the neighbouring button, which is only final now
        PlaceNewsButton()
        return
    end
    db()
    PositionMinimapButton()
    StyleNewsButton()
    PlaceNewsButton()
    if EditModeManagerFrame and EditModeManagerFrame:IsShown() then SetEditing(true) end
    mm.UpdateBadge()
    local n = UnreadCount()
    if n > 0 then
        print(L("|cff4dccffForever News:|r %d unread patch notes. Open with /fnews"):format(n))
    end
end)

SLASH_FOREVERNEWS1 = "/fnews"
SLASH_FOREVERNEWS2 = "/forevernews"
SlashCmdList["FOREVERNEWS"] = function(msg)
    msg = strtrim((msg or ""):lower())
    if msg == "reset" then
        db().newsPos = nil
        PlaceNewsButton()
        print(L("|cff4dccffForever News:|r News button is back at its default spot beneath the chat buttons."))
    else
        Toggle()
    end
end
